// Additional locales are available immediately; untranslated strings fall back to English.
for(const code of ['hi','bn','ru','id','tr','vi','th','sw','ur','it','fil'])catalogs[code]=en;
export function translate(locale,source){
 if(!locale||locale==='zh-CN')return source;
 if(locale==='zh-TW')return catalogs['zh-TW']?.[source]??source;
 const language=locale.split('-')[0];
 return catalogs[locale]?.[source]??catalogs[language]?.[source]??en[source]??source;
}

